52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
58	
59	    /**
60	     * Remembers, per seen {@code Idempotency-Key} header, the id of the owner originally created for
61	     * that key, so a repeated create carrying the same key returns that owner instead of creating a
62	     * duplicate. Kept in memory and keyed on the opaque client-supplied value.
63	     */
64	    private static final java.util.Map<String, Integer> IDEMPOTENCY_KEYS =
65	        new java.util.concurrent.ConcurrentHashMap<>();
66	
67	    private final ClinicService clinicService;
68	
69	    private final OwnerMapper ownerMapper;
70	
71	    private final PetMapper petMapper;
72	
73	    private final VisitMapper visitMapper;
74	
75	    public OwnerRestControllerV1(ClinicService clinicService,
76	                                 OwnerMapper ownerMapper,
77	                                 PetMapper petMapper,
78	                                 VisitMapper visitMapper) {
79	        this.clinicService = clinicService;
80	        this.ownerMapper = ownerMapper;
81	        this.petMapper = petMapper;
82	        this.visitMapper = visitMapper;
83	    }
84	
85	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
86	    @Override
87	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
88	        Collection<Owner> owners;
89	        if (lastName != null) {
90	            owners = this.clinicService.findOwnerByLastName(lastName);
91	        } else {
92	            owners = this.clinicService.findAllOwners();
93	        }
94	        if (owners.isEmpty()) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
103	        Owner owner = this.clinicService.findOwnerById(ownerId);
104	        if (owner == null) {
105	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
106	        }
107	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
108	    }
109	
110	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
111	    @Override
112	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
113	        // Idempotent create: if this request carries an 'Idempotency-Key' we have already seen, return
114	        // the owner originally created for that key with 200 OK, rather than creating a duplicate (which
115	        // the identity/household duplicate rules would otherwise reject with 409).
116	        String idempotencyKey = currentIdempotencyKey();
117	        if (idempotencyKey != null) {
118	            Integer existingId = IDEMPOTENCY_KEYS.get(idempotencyKey);
119	            if (existingId != null) {
120	                Owner existing = this.clinicService.findOwnerById(existingId);
121	                if (existing != null) {
122	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
123	                }
124	            }
125	        }
126	        HttpHeaders headers = new HttpHeaders();
127	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
128	        applyAddress(owner);
129	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
130	        owner.setTelephone(normalizedTelephone);
131	        owner.setEmail(normalizeEmail(owner.getEmail()));
132	        validateEmailDomain(owner.getEmail());
133	        validatePostcode(owner.getPostcode(), owner.getCity());
134	        java.time.LocalDate serverDate = java.time.LocalDate.now();
135	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(serverDate)) {
136	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
137	                "Registration date must not be later than the current server date");
138	        }
139	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() != null
140	            ? owner.getRegistrationDate() : serverDate;
141	        java.time.LocalDate businessDate = toBusinessDay(effectiveDate);
142	        owner.setRegistrationDate(businessDate);
143	        long createdToday = this.clinicService.findAllOwners().stream()
144	            .map(Owner::getRegistrationDate)
145	            .filter(businessDate::equals)
146	            .count();
147	        if (createdToday >= 100) {
148	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
149	                "The maximum number of owners for today has already been reached");
150	        }
151	        owner.setBulkSignupWarning(createdToday > 80);
152	        // The household is keyed deterministically on (normalized last name, postcode): every owner
153	        // computes the same householdId from those two fields, so owners sharing a last name and
154	        // postcode belong to the same household automatically, without any explicit linking.
155	        String lastNameKey = normalizeForHousehold(owner.getLastName());
156	        String householdId = householdId(lastNameKey, owner.getPostcode());
157	        owner.setHouseholdId(householdId);
158	        // Soft-deleted owners are excluded from all duplicate/identity detection: a deleted owner
159	        // no longer blocks a new owner that would otherwise match it.
160	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
161	            .filter(existing -> !existing.isDeleted())
162	            .filter(existing -> householdId.equals(
163	                householdId(normalizeForHousehold(existing.getLastName()), existing.getPostcode())))
164	            .toList();
165	        // All duplicate detection is expressed through the single derived identityKey
166	        // (telephone|email|householdId); a new owner is rejected only when its whole key matches.
167	        String identityKey = owner.getIdentityKey();
168	        boolean identityInUse = this.clinicService.findAllOwners().stream()
169	            .filter(existing -> !existing.isDeleted())
170	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
171	        if (identityInUse) {
172	            throw new ResponseStatusException(HttpStatus.CONFLICT,
173	                "An owner with this identity already exists");
174	        }
175	        // Because the household is keyed on (last name, postcode), a second owner sharing a last name
176	        // and postcode with an existing owner is the same household and is rejected as a household
177	        // duplicate (409). Declaring 'sharesHousehold' only bypasses this block, creating the owner as
178	        // a declared household member.
179	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
180	        // A new owner sharing a household is normally rejected as a duplicate. It is admitted either
181	        // when it declares the shared household, or when it is distinguishable from every existing
182	        // member by carrying its own email address (a distinct contact); in the latter case it joins
183	        // the household as an (undeclared) member whose membership level is capped below.
184	        boolean distinguishableByEmail = owner.getEmail() != null && !owner.getEmail().isBlank()
185	            && householdMembers.stream()
186	                .noneMatch(existing -> owner.getEmail().equalsIgnoreCase(existing.getEmail()));
187	        boolean joinsExistingHousehold = !householdMembers.isEmpty()
188	            && !declaredHouseholdMember && distinguishableByEmail;
189	        if (!householdMembers.isEmpty() && !declaredHouseholdMember && !distinguishableByEmail) {
190	            throw new ResponseStatusException(HttpStatus.CONFLICT,
191	                "An owner in this household already exists");
192	        }
193	        String cityKey = normalizeForHousehold(owner.getCity());
194	        long cityCount = this.clinicService.findAllOwners().stream()
195	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(cityKey))
196	            .count();
197	        if (cityCount >= 50) {
198	            throw new ResponseStatusException(HttpStatus.CONFLICT,
199	                "This city already has the maximum number of owners");
200	        }
201	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
202	        owner.setHouseholdSize(householdMembers.size() + 1);
203	        // A new owner joining an existing household cannot rank more than one level above the current
204	        // maximum membership level among their household members: its level is capped there. With no
205	        // existing household member (the usual case) no cap applies and the level stays as derived.
206	        if (joinsExistingHousehold) {
207	            int naturalLevel = Owner.membershipLevel(Owner.membershipPoints(owner));
208	            int maxMemberLevel = householdMembers.stream()
209	                .mapToInt(Owner::effectiveMembershipLevel)
210	                .max().orElse(0);
211	            owner.setMembershipLevel(Math.min(naturalLevel, maxMemberLevel + 1));
212	        }
213	        // The former soft-match (same last name and postcode, different telephone) now coincides
214	        // exactly with the household key: such an owner is either rejected as a household duplicate
215	        // above, or, when it declares 'sharesHousehold', created as a declared household member. A
216	        // declared member is not a suspected duplicate, so no owner is ever flagged here.
217	        owner.setPossibleDuplicate(false);
218	        owner.setPossibleDuplicateOf(null);
219	        owner.setCustomerCode(deduplicateCustomerCode(customerCode(owner.getCity(), owner.getPostcode(),
220	            owner.getTelephone(), owner.getLastName())));
221	        this.clinicService.saveOwner(owner);
222	        if (idempotencyKey != null) {
223	            IDEMPOTENCY_KEYS.put(idempotencyKey, owner.getId());
224	        }
225	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
226	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
227	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel(),
228	            ownerDto.getMembershipNumber());
229	        headers.setLocation(UriComponentsBuilder.newInstance()
230	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
231	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
232	    }
233	
234	    /**
235	     * Reads the current request's {@code Idempotency-Key} header, if any. Returns the trimmed header
236	     * value, or {@code null} when the header is absent, blank, or there is no active request (so a
237	     * request without the header behaves exactly as before).
238	     *
239	     * @return the non-blank idempotency key for the current request, or {@code null}
240	     */
241	    private String currentIdempotencyKey() {
242	        org.springframework.web.context.request.RequestAttributes attrs =
243	            org.springframework.web.context.request.RequestContextHolder.getRequestAttributes();
244	        if (!(attrs instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttrs)) {
245	            return null;
246	        }
247	        String key = servletAttrs.getRequest().getHeader("Idempotency-Key");
248	        if (key == null || key.isBlank()) {
249	            return null;
250	        }
251	        return key.trim();
252	    }
253	
254	    /**
255	     * The fixed public-holiday calendar the business-day roll skips. When an adjusted registration
256	     * date lands on one of these dates it is rolled forward to the next non-holiday business day.
257	     */
258	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
259	        java.time.LocalDate.parse("2026-01-01"), java.time.LocalDate.parse("2026-01-26"),
260	        java.time.LocalDate.parse("2026-04-25"), java.time.LocalDate.parse("2026-12-25"),
261	        java.time.LocalDate.parse("2026-12-28"));
262	
263	    /**
264	     * Rolls a registration date forward to a business day. A Saturday, Sunday or listed public
265	     * holiday is advanced one day at a time until it lands on a weekday that is not a public holiday;
266	     * a plain weekday is returned unchanged. This is applied to the effective registration date
267	     * (whether supplied in the request or defaulted to the server date) so that every stored
268	     * {@code registrationDate}, and any value derived from it, lands on a business day.
269	     *
270	     * @param date the effective registration date
271	     * @return the same date if it is a non-holiday weekday, otherwise the next non-holiday business day
272	     */
273	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
274	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
275	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
276	            || PUBLIC_HOLIDAYS.contains(date)) {
277	            date = date.plusDays(1);
278	        }
279	        return date;
280	    }
281	
282	    /**
283	     * Counts the owners that already exist (before the current create) whose first and last names
284	     * both match the supplied names, compared case-insensitively. The returned value is captured on
285	     * the new owner at creation time and does not change as further owners are added later.
286	     *
287	     * @param firstName the new owner's first name
288	     * @param lastName  the new owner's last name
289	     * @return the number of pre-existing namesake owners
290	     */
291	    private int namesakeCount(String firstName, String lastName) {
292	        return (int) this.clinicService.findAllOwners().stream()
293	            .filter(existing -> existing.getFirstName() != null
294	                && existing.getFirstName().equalsIgnoreCase(firstName)
295	                && existing.getLastName() != null
296	                && existing.getLastName().equalsIgnoreCase(lastName))
297	            .count();
298	    }
299	
300	    /**
301	     * Builds the customer code for a new owner, formatted {@code '<REGION>-<HASH8>'} where
302	     * {@code REGION} is the canonical region derived from the owner's postcode (falling back to
303	     * the city when the postcode is absent or in no known range, see
304	     * {@link org.springframework.samples.petclinic.mapper.Localities#forCityAndPostcode}), and
305	     * {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the
306	     * normalized telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). Unlike
307	     * the previous city-prefixed scheme it carries no per-city sequence number, so the identity is
308	     * a pure function of the owner's region, telephone and last name.
309	     *
310	     * @param city                the owner's city
311	     * @param postcode            the owner's postcode, may be {@code null}
312	     * @param normalizedTelephone the owner's telephone, already normalized to E.164
313	     * @param lastName            the owner's last name
314	     * @return the assigned customer code
315	     */
316	    private String customerCode(String city, String postcode, String normalizedTelephone, String lastName) {
317	        String region = org.springframework.samples.petclinic.mapper.Localities
318	            .forCityAndPostcode(city, postcode);
319	        String hash8 = sha256UpperHex((normalizedTelephone == null ? "" : normalizedTelephone)
320	            + (lastName == null ? "" : lastName), 8);
321	        return region + "-" + hash8;
322	    }
323	
324	    /**
325	     * Ensures the computed {@code customerCode} is unique across existing owners. When {@code baseCode}
326	     * does not collide with any existing owner's {@code customerCode} it is returned unchanged.
327	     * Otherwise {@code '-<n>'} is appended, using the smallest {@code n} of 2 or more that yields a
328	     * value not already in use, and that de-duplicated code is returned.
329	     *
330	     * @param baseCode the freshly computed customer code
331	     * @return {@code baseCode} if unused, otherwise {@code baseCode + "-" + n} for the smallest free n
332	     */
333	    private String deduplicateCustomerCode(String baseCode) {
334	        java.util.Set<String> inUse = this.clinicService.findAllOwners().stream()
335	            .map(org.springframework.samples.petclinic.model.Owner::getCustomerCode)
336	            .filter(java.util.Objects::nonNull)
337	            .collect(java.util.stream.Collectors.toSet());
338	        if (!inUse.contains(baseCode)) {
339	            return baseCode;
340	        }
341	        int n = 2;
342	        while (inUse.contains(baseCode + "-" + n)) {
343	            n++;
344	        }
345	        return baseCode + "-" + n;
346	    }
347	
348	    /**
349	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
350	     * UTF-8 bytes of {@code value}.
351	     *
352	     * @param value  the source value to hash
353	     * @param length the number of leading hex characters to return
354	     * @return the leading upper-case hex characters of the digest
355	     */
356	    private String sha256UpperHex(String value, int length) {
357	        try {
358	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
359	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
360	            StringBuilder sb = new StringBuilder(digest.length * 2);
361	            for (byte b : digest) {
362	                sb.append(String.format("%02x", b));
363	            }
364	            return sb.substring(0, length).toUpperCase(java.util.Locale.ROOT);
365	        }
366	        catch (java.security.NoSuchAlgorithmException e) {
367	            throw new IllegalStateException("SHA-256 not available", e);
368	        }
369	    }
370	
371	    /**
372	     * Normalizes a street address applied whenever an owner is created: leading and trailing
373	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the
374	     * value is upper-cased, and common street-type abbreviations are expanded to their full form
375	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The expansion is applied
376	     * per whitespace-delimited token, so only standalone abbreviations are expanded. A {@code null}
377	     * value normalizes to the empty string. So {@code '  12  main  st '} becomes
378	     * {@code '12 MAIN STREET'}.
379	     *
380	     * @param address the raw address as submitted, or {@code null} when absent
381	     * @return the normalized address, or the empty string when the value is blank
382	     */
383	    /**
384	     * Resolves and normalizes an owner's postal address, accepting either the structured form
385	     * ({@code addressLine1} plus an optional {@code addressLine2}) or the flat {@code address}
386	     * input for backward compatibility. The structured form is preferred: when a non-blank
387	     * {@code addressLine1} is supplied, both structured lines are normalized (see
388	     * {@link #normalizeAddress(String)}) and the stored {@code address} is composed from them —
389	     * the normalized {@code addressLine1}, with a single space and the normalized
390	     * {@code addressLine2} appended when an {@code addressLine2} is present. Otherwise the flat
391	     * {@code address} input is normalized and stored, and the structured lines are cleared.
392	     *
393	     * <p>An owner is valid only when it supplies an address in one of these forms; a request with
394	     * neither a non-blank {@code addressLine1} nor a non-blank flat {@code address} is rejected.
395	     *
396	     * @param owner the owner whose address fields are resolved and normalized in place
397	     * @throws ResponseStatusException with a 400 status when no address is supplied in either form
398	     */
399	    private void applyAddress(Owner owner) {
400	        String line1 = normalizeAddress(owner.getAddressLine1());
401	        String line2 = normalizeAddress(owner.getAddressLine2());
402	        String flat = normalizeAddress(owner.getAddress());
403	        String composed;
404	        if (!line1.isEmpty()) {
405	            composed = line2.isEmpty() ? line1 : line1 + " " + line2;
406	            owner.setAddressLine1(line1);
407	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
408	        } else {
409	            composed = flat;
410	            owner.setAddressLine1(null);
411	            owner.setAddressLine2(null);
412	        }
413	        if (composed.isEmpty()) {
414	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
415	                "Address must not be blank after normalization");
416	        }
417	        owner.setAddress(composed);
418	    }
419	
420	    private String normalizeAddress(String address) {
421	        String collapsed = (address == null ? "" : address)
422	            .trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
423	        if (collapsed.isEmpty()) {
424	            return "";
425	        }
426	        String[] tokens = collapsed.split(" ");
427	        for (int i = 0; i < tokens.length; i++) {
428	            switch (tokens[i]) {
429	                case "ST" -> tokens[i] = "STREET";
430	                case "RD" -> tokens[i] = "ROAD";
431	                case "AVE" -> tokens[i] = "AVENUE";
432	                default -> { }
433	            }
434	        }
435	        return String.join(" ", tokens);
436	    }
437	
438	    /**
439	     * Normalizes a value for household-duplicate comparison: leading and trailing whitespace is
440	     * trimmed, any internal run of whitespace is collapsed to a single space, and the result is
441	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to the
442	     * empty string.
443	     *
444	     * @param value the raw value (last name or address) as submitted
445	     * @return the normalized comparison key
446	     */
447	    private String normalizeForHousehold(String value) {
448	        if (value == null) {
449	            return "";
450	        }
451	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
452	    }
453	
454	    /**
455	     * Derives the stable shared household identifier for a household, keyed on the normalized last
456	     * name and address. Because it is a pure function of those normalized keys, every owner in the
457	     * same household deterministically computes the same value. The identifier is the first 12
458	     * upper-case hex characters of the SHA-256 digest of the two keys joined with a NUL separator
459	     * (the separator prevents distinct name/address pairs from colliding).
460	     *
461	     * @param lastNameKey the normalized last-name comparison key
462	     * @param addressKey  the normalized address comparison key
463	     * @return the stable household identifier
464	     */
465	    private String householdId(String lastNameKey, String postcode) {
466	        String seed = lastNameKey + "|" + (postcode == null ? "" : postcode);
467	        try {
468	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
469	                .digest(seed.getBytes(java.nio.charset.StandardCharsets.UTF_8));
470	            StringBuilder sb = new StringBuilder(digest.length * 2);
471	            for (byte b : digest) {
472	                sb.append(String.format("%02x", b));
473	            }
474	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
475	        }
476	        catch (java.security.NoSuchAlgorithmException e) {
477	            throw new IllegalStateException("SHA-256 not available", e);
478	        }
479	    }
480	
481	    /**
482	     * The exact number of national (subscriber) digits required for a given country calling code,
483	     * i.e. the digits that follow the country code in an E.164 number. A country code that is not
484	     * listed here has no fixed-length requirement beyond the general 8-to-15-digit E.164 bound.
485	     * Australia ({@code '+61'}) requires 9 national digits and the NANP ({@code '+1'}) requires 10.
486	     */
487	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
488	        java.util.Map.of("61", 9, "1", 10);
489	
490	    /**
491	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets (indeed any
492	     * non-digit character) are stripped. If the submitted value carries a leading {@code '+'}
493	     * its country code is kept as-is; otherwise the default country code {@code '+61'} is
494	     * assumed and a single leading {@code '0'} is dropped from the national digits. The
495	     * resulting value must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'}
496	     * is stored as {@code '+61412345678'}.
497	     *
498	     * <p>In addition, when the number's country code has a fixed national-number length (see
499	     * {@link #NATIONAL_NUMBER_LENGTHS}), the national digits that follow the country code must
500	     * match that length exactly: {@code '+61'} requires 9 national digits and {@code '+1'}
501	     * requires 10. So {@code '+61 123'} is rejected because its 3 national digits are not 9.
502	     *
503	     * @param telephone the raw telephone number as submitted
504	     * @return the normalized E.164 telephone number
505	     * @throws ResponseStatusException with a 400 status if the value cannot form a valid E.164
506	     *         number (8 to 15 digits after the '+'), or if its national-number length is wrong
507	     *         for its country code
508	     */
509	    private String normalizeTelephone(String telephone) {
510	        String raw = telephone == null ? "" : telephone.trim();
511	        String digits = raw.replaceAll("\\D", "");
512	        String e164;
513	        if (raw.startsWith("+")) {
514	            e164 = "+" + digits;
515	        } else {
516	            if (digits.startsWith("0")) {
517	                digits = digits.substring(1);
518	            }
519	            e164 = "+61" + digits;
520	        }
521	        int digitCount = e164.length() - 1;
522	        if (digitCount < 8 || digitCount > 15) {
523	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
524	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
525	        }
526	        validateNationalNumberLength(e164);
527	        return e164;
528	    }
529	
530	    /**
531	     * Validates that an E.164 number's national-number length is correct for its country code.
532	     * The country code is matched by longest known prefix (so {@code '+61'} is preferred over
533	     * {@code '+1'} would-be matches); when the code has a fixed national-number length the digits
534	     * following it must match exactly. Country codes without a fixed length are left unchecked.
535	     *
536	     * @param e164 the normalized E.164 number (a {@code '+'} followed by digits)
537	     * @throws ResponseStatusException with a 400 status if the national-number length is wrong
538	     *         for the country code
539	     */
540	    private void validateNationalNumberLength(String e164) {
541	        String allDigits = e164.substring(1);
542	        String bestCode = null;
543	        for (String code : NATIONAL_NUMBER_LENGTHS.keySet()) {
544	            if (allDigits.startsWith(code)
545	                    && (bestCode == null || code.length() > bestCode.length())) {
546	                bestCode = code;
547	            }
548	        }
549	        if (bestCode == null) {
550	            return;
551	        }
552	        int nationalLength = allDigits.length() - bestCode.length();
553	        int required = NATIONAL_NUMBER_LENGTHS.get(bestCode);
554	        if (nationalLength != required) {
555	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
556	                "Telephone for country code '+" + bestCode + "' must have " + required
557	                    + " national digits");
558	        }
559	    }
560	
561	    /**
562	     * The inclusive 4-digit postcode range permitted for each canonical region, keyed by the
563	     * region derived from the owner's city ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
564	     * {@code Brisbane -> QLD}): NSW {@code 2000-2099}, VIC {@code 3000-3099}, QLD
565	     * {@code 4000-4099}. A city whose region is not listed here accepts any 4-digit postcode.
566	     */
567	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
568	        "NSW", new int[] {2000, 2099},
569	        "VIC", new int[] {3000, 3099},
570	        "QLD", new int[] {4000, 4099});
571	
572	    /**
573	     * Validates an owner's optional postcode against their city's region. The postcode is only
574	     * checked when present (a {@code null} postcode is accepted, keeping the request contract
575	     * backward-compatible). Its four-digit shape is already enforced by Bean Validation on the
576	     * request DTO. When the city maps to a known region (see {@link #REGION_POSTCODE_RANGES}) the
577	     * postcode must fall within that region's inclusive range; a city with no known region accepts
578	     * any 4-digit postcode.
579	     *
580	     * @param postcode the owner's postcode as submitted, or {@code null} when absent
581	     * @param city     the owner's city, used to derive the region whose range applies
582	     * @throws ResponseStatusException with a 400 status when a supplied postcode is out of range
583	     *         for the city's region
584	     */
585	    private void validatePostcode(String postcode, String city) {
586	        if (postcode == null) {
587	            return;
588	        }
589	        String region = org.springframework.samples.petclinic.mapper.Localities.forCity(city);
590	        int[] range = REGION_POSTCODE_RANGES.get(region);
591	        if (range == null) {
592	            return;
593	        }
594	        int value = Integer.parseInt(postcode);
595	        if (value < range[0] || value > range[1]) {
596	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
597	                "Postcode " + postcode + " is not valid for region " + region);
598	        }
599	    }
600	
601	    /**
602	     * Normalizes an optional email address by lower-casing it. Syntactic validity is enforced
603	     * by Bean Validation on the request DTO, so a value reaching this point is either {@code null}
604	     * (absent) or already valid.
605	     *
606	     * @param email the email address as submitted, or {@code null} when absent
607	     * @return the lower-cased email, or {@code null} when absent
608	     */
609	    private String normalizeEmail(String email) {
610	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
611	    }
612	
613	    /**
614	     * The set of disposable email domains an owner's email may not use. These throwaway-mailbox
615	     * providers are rejected because they cannot be relied on for durable contact.
616	     */
617	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
618	        "mailinator.com", "tempmail.com", "guerrillamail.com");
619	
620	    /**
621	     * Rejects an owner whose email domain is on the disposable-domain blocklist. The email has
622	     * already been normalized to lower-case, so the domain (the part after the last {@code '@'}) is
623	     * compared case-insensitively against {@link #DISPOSABLE_EMAIL_DOMAINS}. A {@code null} email
624	     * (absent) is accepted, keeping the field optional.
625	     *
626	     * @param email the normalized email address, or {@code null} when absent
627	     * @throws ResponseStatusException with a 400 status when the email domain is blocklisted
628	     */
629	    private void validateEmailDomain(String email) {
630	        if (email == null) {
631	            return;
632	        }
633	        int at = email.lastIndexOf('@');
634	        if (at < 0) {
635	            return;
636	        }
637	        String domain = email.substring(at + 1);
638	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
639	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
640	                "Email domain " + domain + " is not allowed");
641	        }
642	    }
643	
644	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
645	    @Override
646	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
647	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
648	        if (currentOwner == null) {
649	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
650	        }
651	        currentOwner.setAddress(ownerFieldsDto.getAddress());
652	        currentOwner.setCity(ownerFieldsDto.getCity());
653	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
654	        currentOwner.setLastName(ownerFieldsDto.getLastName());
655	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
656	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
657	        this.clinicService.saveOwner(currentOwner);
658	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
659	    }
660	
661	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
662	    @Transactional
663	    @Override
664	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
665	        Owner owner = this.clinicService.findOwnerById(ownerId);
666	        if (owner == null) {
667	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
668	        }
669	        // Soft delete: flag the owner deleted and retain the row rather than removing it.
670	        owner.setDeleted(true);
671	        this.clinicService.saveOwner(owner);
672	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
673	    }
674	
675	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
676	    @Override
677	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
678	        Owner owner = this.clinicService.findOwnerById(ownerId);
679	        if (owner == null) {
680	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
681	        }
682	        HttpHeaders headers = new HttpHeaders();
683	        Pet pet = petMapper.toPet(petFieldsDto);
684	        owner.setId(ownerId);
685	        pet.setOwner(owner);
686	        pet.getType().setName(null);
687	        this.clinicService.savePet(pet);
688	        PetDto petDto = petMapper.toPetDto(pet);
689	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
690	            .buildAndExpand(pet.getId()).toUri());
691	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
692	    }
693	
694	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
695	    @Override
696	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
697	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
698	        if (currentOwner != null) {
699	            Pet currentPet = this.clinicService.findPetById(petId);
700	            if (currentPet != null) {
701	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
702	                currentPet.setName(petFieldsDto.getName());
703	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
704	                this.clinicService.savePet(currentPet);
705	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
706	            }
707	        }
708	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
709	    }
710	
711	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
712	    @Override
713	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
714	        HttpHeaders headers = new HttpHeaders();
715	        Visit visit = visitMapper.toVisit(visitFieldsDto);
716	        Pet pet = new Pet();
717	        pet.setId(petId);
718	        visit.setPet(pet);
719	        this.clinicService.saveVisit(visit);
720	        VisitDto visitDto = visitMapper.toVisitDto(visit);
721	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
722	            .buildAndExpand(visit.getId()).toUri());
723	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
724	    }
725	
726	
727	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
728	    @Override
729	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
730	        Owner owner = this.clinicService.findOwnerById(ownerId);
731	        if (owner != null) {
732	            Pet pet = owner.getPet(petId);
733	            if (pet != null) {
734	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
735	            }
736	        }
737	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
738	    }
739	}
