171	    public void setTelephone(String telephone) {
172	        this.telephone = telephone;
173	    }
174	
175	    /**
176	     * The known E.164 country calling codes used to split the stored telephone into its country
177	     * code and national digits when formatting {@link #getTelephoneDisplay()}. Ordered
178	     * longest-first so the most specific code wins; this mirrors the codes the application
179	     * recognises elsewhere (Australia {@code '+61'} and the NANP {@code '+1'}).
180	     */
181	    private static final List<String> KNOWN_COUNTRY_CODES = List.of("61", "1");
182	
183	    /**
184	     * The stored E.164 {@link #telephone} formatted for humans: the country code, a space, then the
185	     * national digits grouped in threes from the left and separated by spaces. So the stored
186	     * {@code '+61412345678'} is displayed as {@code '+61 412 345 678'}. The raw {@link #telephone}
187	     * itself is left in E.164 form. A {@code null} telephone yields {@code null}, and a value not in
188	     * E.164 form (no leading {@code '+'}) is returned unchanged.
189	     *
190	     * @return the human-formatted telephone, or {@code null} when no telephone is stored
191	     */
192	    @Transient
193	    public String getTelephoneDisplay() {
194	        if (this.telephone == null || !this.telephone.startsWith("+")) {
195	            return this.telephone;
196	        }
197	        String allDigits = this.telephone.substring(1);
198	        if (allDigits.isEmpty()) {
199	            return this.telephone;
200	        }
201	        String countryCode = null;
202	        for (String code : KNOWN_COUNTRY_CODES) {
203	            if (allDigits.startsWith(code)) {
204	                countryCode = code;
205	                break;
206	            }
207	        }
208	        if (countryCode == null) {
209	            countryCode = allDigits.substring(0, 1);
210	        }
211	        String national = allDigits.substring(countryCode.length());
212	        StringBuilder display = new StringBuilder("+").append(countryCode);
213	        for (int i = 0; i < national.length(); i += 3) {
214	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
215	        }
216	        return display.toString();
217	    }
