462	    /**
463	     * A single Luhn check digit (0-9) computed over the digits contained in the
464	     * {@code customerCode}. Non-digit characters (such as the letter prefixes and the
465	     * separators) are ignored; a {@code null} customer code is treated as having no digits.
466	     *
467	     * @return the Luhn check digit for the customer code
468	     */
469	    @Transient
470	    public int getCheckDigit() {
471	        String source = this.customerCode == null ? "" : this.customerCode;
472	        int sum = 0;
473	        boolean dbl = true;
474	        for (int i = source.length() - 1; i >= 0; i--) {
475	            char c = source.charAt(i);
476	            if (c < '0' || c > '9') {
477	                continue;
478	            }
479	            int d = c - '0';
480	            if (dbl) {
481	                d *= 2;
482	                if (d > 9) {
483	                    d -= 9;
484	                }
485	            }
486	            sum += d;
487	            dbl = !dbl;
488	        }
489	        return (10 - (sum % 10)) % 10;
490	    }
